import React, { useMemo, useEffect } from 'react';
import { View, Text, StyleSheet, ViewStyle } from 'react-native';
import Animated, { useSharedValue, useAnimatedStyle, withSpring, withDelay, interpolate } from 'react-native-reanimated';
import { LinearGradient } from 'expo-linear-gradient';
import { useTheme } from '../../context/ThemeContext';
import { SPACING, FONTS, BORDER_RADIUS} from '../../constants/theme';

interface CardProps {
  children: React.ReactNode;
  title?: string;
  subtitle?: string;
  rightAction?: React.ReactNode;
  gradient?: readonly [string, string];
  style?: ViewStyle;
  noPadding?: boolean;
  /** Enable entry animation (fade-in + slide-up) */
  animated?: boolean;
  /** Delay before entry animation starts (ms) */
  animationDelay?: number;
  /** Test ID for E2E targeting */
  testID?: string;
}

export default function Card({
  children,
  title,
  subtitle,
  rightAction,
  gradient,
  style,
  noPadding = false,
  animated = false,
  animationDelay = 0,
  testID,
}: CardProps) {
  const { colors } = useTheme();
  const styles = useMemo(() => createStyles(colors), [colors]);

  // Entry animation
  const entryProgress = useSharedValue(0);
  const entryStyle = useAnimatedStyle(() => ({
    opacity: interpolate(entryProgress.value, [0, 1], [0, 1]),
    transform: [{
      translateY: interpolate(entryProgress.value, [0, 1], [20, 0]),
    }],
  }));

  useEffect(() => {
    if (animated) {
      entryProgress.value = withDelay(animationDelay, withSpring(1, { stiffness: 120, damping: 12 }));
    }
  }, [animated, animationDelay, entryProgress]);

  return (
    <Animated.View
      style={[
        styles.container,
        gradient && styles.gradientContainer,
        animated ? entryStyle : {},
        style,
      ]}
      testID={testID}
    >
      {gradient && (
        <View style={StyleSheet.absoluteFill}>
          <LinearGradient
            colors={gradient}
            start={{ x: 0, y: 0 }}
            end={{ x: 1, y: 1 }}
            style={[StyleSheet.absoluteFill, { borderRadius: BORDER_RADIUS.lg }]}
          />
        </View>
      )}
      {(title || subtitle || rightAction) && (
        <View style={styles.header}>
          <View style={styles.headerLeft}>
            {title && <Text style={styles.title}>{title}</Text>}
            {subtitle && <Text style={styles.subtitle}>{subtitle}</Text>}
          </View>
          {rightAction && <View>{rightAction}</View>}
        </View>
      )}
      <View style={[!noPadding && styles.content]}>
        {children}
      </View>
    </Animated.View>
  );
}

const createStyles = (colors: any) => StyleSheet.create({
  container: {
    backgroundColor: colors.bgCard,
    borderRadius: BORDER_RADIUS.lg,
    borderWidth: 1,
    borderColor: colors.border,
    overflow: 'hidden',
    boxShadow: '0px 1px 2px rgba(0,0,0,0.3)',
  },
  gradientContainer: {
    borderWidth: 1,
    borderColor: colors.border,
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: SPACING.lg,
    paddingTop: SPACING.lg,
    paddingBottom: SPACING.md,
  },
  headerLeft: {
    flex: 1,
  },
  title: {
    ...FONTS.semiBold,
    fontSize: FONTS.size.lg,
    color: colors.text,
  },
  subtitle: {
    ...FONTS.regular,
    fontSize: FONTS.size.sm,
    color: colors.textSecondary,
    marginTop: 2,
  },
  content: {
    padding: SPACING.lg,
    paddingTop: 0,
  },
});
